@startuml

class SensorController {
}

class Apartment {
  + address : string
  + email : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendor_id : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counter_reading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
}

enum Unit {
  CELSIUS
  WATT
}

Apartment "1" *-- "2..*" Room
Apartment "1" -- "1" SensorController
SensorController "1" -- "*" Inhabitant
SensorController "1" -- "*" Apartment
SensorController "1" -- "*" Sensor
Room "1" -- "1" Sensor
Sensor "1" *-- "*" MeasuredValue
EMonitor "1" -- "*" Sensor

@enduml

